"""Owner-only scientific admission overlay for the frozen development family.

The original expected-outcome reward remains a diagnostic. This module admits
sources before rollout derivation and never authenticates an assessment: callers
must rebind the original commitment, evidence, adopted executable and replay.
Neither a policy assertion nor an ``authenticated=True`` flag is a receipt.
"""

from __future__ import annotations

import copy
import math

from .contracts import digest

VERSION = "ndfeb-reward-qualification-v1"
REQUIRED_COVERAGE = frozenset({"advancement", "retention", "withholding"})
# A new response law or newly qualified decision needs a new reviewed registry
# and gate version; changing a favorable episode cannot qualify this source.
CASE_RULES = {
    "revision_off690_peak": (False, (), "diagnostic_only"),
    "retention_resolvable": (False, (), "diagnostic_only"),
    "ambiguity": (False, (), "diagnostic_only"),
    "nonidentifiability": (True, ("withholding",), "bounded_available_method_withholding"),
}
_SCORED_STATUSES = {
    "supported_advancement": (1.0, "successful_advancement"),
    "wrong_advancement": (-1.0, "failed_advancement"),
    "certified_reference_retention": (1.0, "reference_retention"),
    "wrong_retention": (-1.0, "reference_retention"),
    "evidence_supported_withholding_unavailable_endpoint": (1.0, "withholding"),
    "withholding_without_resolution": (0.0, "withholding"),
    "assessed_but_unresolved_nomination": (0.0, "unresolved_nomination"),
    "invalid_submission": (-1.0, "invalid_commitment"),
}


def _hash(value):
    try:
        return digest(value)
    except (TypeError, ValueError):
        return None


def validate_registry(registry, *, worlds, public_task, reward_contract):
    """Check canonical JSON bindings, case coverage and this version's decisions.

    The caller must obtain the owner registry from its pinned study manifest.
    Hash equality detects changed inputs; it does not authenticate who made them.
    """
    errors = []
    if not isinstance(registry, dict) or not isinstance(worlds, dict):
        return {"schema": VERSION, "valid": False, "errors": ["registry_and_worlds_must_be_objects"],
                "status": "blocked_qualification_binding"}
    if registry.get("schema") != VERSION:
        errors.append("qualification_schema")
    if _hash(registry) is None:
        errors.append("registry_not_finite_json")
    bindings = registry.get("bindings")
    if not isinstance(bindings, dict):
        bindings = {}
    for name, value in (("worlds_sha256", worlds), ("public_task_sha256", public_task),
                        ("reward_contract_sha256", reward_contract)):
        actual = _hash(value) if isinstance(value, dict) else None
        if actual is None or bindings.get(name) != actual:
            errors.append("binding:" + name)
    cases = registry.get("cases")
    if not isinstance(cases, dict):
        cases = {}
    if set(worlds) != set(CASE_RULES) or set(cases) != set(CASE_RULES):
        errors.append("frozen_family_case_set")
    required = registry.get("required_decision_coverage")
    if (not isinstance(required, list) or not all(isinstance(item, str) for item in required)
            or sorted(required) != sorted(REQUIRED_COVERAGE)):
        errors.append("required_decision_coverage")
    for key, (qualified, coverage, scope) in CASE_RULES.items():
        entry = cases.get(key)
        if not isinstance(entry, dict):
            errors.append("case_entry:" + key)
            continue
        world_hash = _hash(worlds.get(key)) if isinstance(worlds.get(key), dict) else None
        if world_hash is None or entry.get("world_sha256") != world_hash:
            errors.append("world_binding:" + key)
        if entry.get("optimization_qualified") is not qualified:
            errors.append("frozen_qualification:" + key)
        if entry.get("decision_coverage") != list(coverage):
            errors.append("frozen_decision_coverage:" + key)
        if entry.get("scope") != scope:
            errors.append("frozen_scope:" + key)
        if not isinstance(entry.get("reason"), str) or not entry["reason"].strip():
            errors.append("qualification_reason:" + key)
    return {"schema": VERSION, "valid": not errors, "errors": errors,
            "status": "registry_bound" if not errors else "blocked_qualification_binding",
            "registry_sha256": _hash(registry), "authentication_performed": False}


def admit_case(case_key, registry, *, worlds, public_task, reward_contract):
    """Admit the source, never an outcome-selected subset of its trajectories."""
    validation = validate_registry(registry, worlds=worlds, public_task=public_task,
                                   reward_contract=reward_contract)
    known = isinstance(case_key, str) and case_key in CASE_RULES
    entry = registry.get("cases", {}).get(case_key, {}) if validation["valid"] and known else {}
    qualified = validation["valid"] and known and entry.get("optimization_qualified") is True
    return {"schema": VERSION, "case_key": case_key, "optimization_qualified": qualified,
            "status": ("source_qualified" if qualified else "blocked_scientific_qualification"
                       if validation["valid"] and known else "blocked_qualification_binding"),
            "reason": entry.get("reason", "unknown_case_or_unbound_qualification"),
            "scope": entry.get("scope"), "decision_coverage": entry.get("decision_coverage", []),
            "registry_sha256": validation.get("registry_sha256"), "validation": validation}


def overlay_assessment(result, *, case_key, registry, worlds, public_task, reward_contract):
    """Preserve an owner-reproduced result and add a separate optimizer gate.

    No missing label becomes zero. An invalid commitment keeps its own category,
    including in the bounded withholding case. This is not runtime authentication.
    """
    admission = admit_case(case_key, registry, worlds=worlds, public_task=public_task,
                           reward_contract=reward_contract)
    result = copy.deepcopy(result)
    status = result.get("status") if isinstance(result, dict) else None
    reward = result.get("reward") if isinstance(result, dict) else None
    expected = _SCORED_STATUSES.get(status) if isinstance(status, str) else None
    category = expected[1] if expected else (
        "unfinished" if status == "awaiting_external_evidence" else
        "unresolved_nomination" if status == "numerical_boundary_unresolved" else "unavailable")
    label_valid = (expected is not None and type(reward) in (int, float)
                   and math.isfinite(reward) and reward == expected[0]
                   and result.get("contract_sha256") == _hash(reward_contract))
    if case_key == "nonidentifiability" and status in (
            "supported_advancement", "certified_reference_retention", "wrong_retention"):
        # No complete joint attainment or global retention label exists in this
        # frozen missing-grain world. A contradictory owner row is not a label.
        label_valid = False
    # Booleans, an unknown status, or a caller's optimization_eligible flag cannot
    # supply an outcome label. Artifact authentication remains the caller's job.
    eligible = admission["optimization_qualified"] and label_valid
    return {"schema": VERSION, "case_key": case_key, "original_assessment": result,
            "original_status": status, "original_reward": reward,
            "action_category": category, "optimizer_reward": reward if eligible else None,
            "optimization_eligible": eligible, "owner_label_well_formed": label_valid,
            "source_admission": admission, "episode_denominator": 1,
            "authentication_performed": False, "five_behavioral_axes_used_as_reward": False}


def admit_schedule(schedule, registry, *, worlds, public_task, reward_contract, results=None):
    """Block derivation unless every scheduled source and decision family qualifies.

    ``schedule`` is a predeclared list of ``episode_id, case_key`` objects. Optional
    owner ``results`` must contain exactly those identities, each with an
    ``assessment`` object. A missing/unverified label blocks the whole group.
    """
    validation = validate_registry(registry, worlds=worlds, public_task=public_task,
                                   reward_contract=reward_contract)
    errors = list(validation["errors"])
    rows = schedule if isinstance(schedule, list) else []
    if not rows:
        errors.append("nonempty_predeclared_schedule_required")
    indexed = {}
    admissions = []
    coverage = set()
    for row in rows:
        if (not isinstance(row, dict) or not isinstance(row.get("episode_id"), str)
                or not row["episode_id"] or not isinstance(row.get("case_key"), str)):
            errors.append("malformed_schedule_identity")
            continue
        key = row["episode_id"]
        if key in indexed:
            errors.append("duplicate_scheduled_episode:" + key)
            continue
        indexed[key] = row["case_key"]
        admitted = admit_case(row["case_key"], registry, worlds=worlds,
                              public_task=public_task, reward_contract=reward_contract)
        admissions.append({"episode_id": key, **admitted})
        if not admitted["optimization_qualified"]:
            errors.append("unqualified_scheduled_source:" + key)
        else:
            coverage.update(admitted["decision_coverage"])
    missing_coverage = sorted(REQUIRED_COVERAGE - coverage)
    if missing_coverage:
        errors.append("missing_qualified_decision_coverage:" + ",".join(missing_coverage))
    overlays = []
    if results is not None:
        found = set()
        for row in results if isinstance(results, list) else []:
            if (not isinstance(row, dict) or not isinstance(row.get("episode_id"), str)
                    or row["episode_id"] not in indexed or row["episode_id"] in found
                    or row.get("case_key") != indexed[row["episode_id"]]):
                errors.append("result_identity_mismatch_or_duplicate")
                continue
            found.add(row["episode_id"])
            overlay = overlay_assessment(row.get("assessment"), case_key=row["case_key"],
                                         registry=registry, worlds=worlds,
                                         public_task=public_task, reward_contract=reward_contract)
            overlays.append({"episode_id": row["episode_id"], **overlay})
            if not overlay["owner_label_well_formed"]:
                errors.append("missing_or_unverified_owner_label:" + row["episode_id"])
        if found != set(indexed):
            errors.append("result_coverage_mismatch")
    return {"schema": VERSION, "training_admissible": not errors,
            "status": "admissible" if not errors else "blocked_qualification_binding"
            if not validation["valid"] else "blocked_scientific_qualification",
            "errors": errors, "planned_episode_count": len(rows),
            "result_count": None if results is None else len(results) if isinstance(results, list) else 0,
            "required_decision_coverage": sorted(REQUIRED_COVERAGE),
            "qualified_decision_coverage": sorted(coverage),
            "missing_decision_coverage": missing_coverage, "source_admissions": admissions,
            "assessment_overlays": overlays, "registry_sha256": validation.get("registry_sha256"),
            "authentication_performed": False}
